        try {
            assertTrue("Can not see unknown key",!bean.contains("mappedProperty","Unknown Key"));
            bean.remove("mappedProperty", "Unknown Key");
            assertTrue("Can not see unknown key",!bean.contains("mappedProperty","Unknown Key"));
        } catch (final Throwable t) {
            fail("Exception: " + t);
        }

